function lastOpenBracketIndex(s) {
  const stack = [];
  const pairs = { ")": "(", "]": "[", "}": "{" };
  let last = -1;
  for (let i = 0; i < s.length; i += 1) {
    const c = s[i];
    if (c === "(" || c === "[" || c === "{") stack.push(i);
    else if (pairs[c]) {
      if (!stack.length || s[stack[stack.length - 1]] !== pairs[c]) return stack.length ? stack[stack.length - 1] : -1;
      stack.pop();
    }
  }
  return stack.length ? stack[stack.length - 1] : -1;
}

function isValid(s) {
  const stack = [];
  const open = { "(": ")", "[": "]", "{": "}" };
  for (const c of s) {
    if (open[c]) stack.push(open[c]);
    else if (!stack.length || stack.pop() !== c) return false;
  }
  return stack.length === 0;
}

